---@class OverseaManagerPersonnelClerkCell
local OverseaManagerPersonnelClerkCell = Class('OverseaManagerPersonnelClerkCell')
local KTool = CS.Engine.Lib.KTool
local MaidCoffeeMgr = import('Game.MaidCoffee.MaidCoffeeMgr')
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
local CanvasGroup = CS.UnityEngine.CanvasGroup
local UIModule = CS.Engine.UI.UIModule
function OverseaManagerPersonnelClerkCell:__init()
    
end

function OverseaManagerPersonnelClerkCell:__delete()
    
end

function OverseaManagerPersonnelClerkCell:Awake()
    self:AddUIClick()
    KTool.SetActive(self.Tips.gameObject,false)
end

function OverseaManagerPersonnelClerkCell:AddUIClick()
    SetButtonAction(self.BtnNode.gameObject, Bind(self,self.OnSelectBtnClick))
end

function OverseaManagerPersonnelClerkCell:Start()

end

function OverseaManagerPersonnelClerkCell:SetAddCallBack(_index)
    self.index = _index
end

function OverseaManagerPersonnelClerkCell:RefreshCellShow(index,ownerId)
    local isLocked,des = MaidCoffeeMgr:GetInstance():GetIsLocked(MaidCoffeeConstants.SelectType.Clerk,index)
    self.isLocked = isLocked
    KTool.SetActive(self.Lock.gameObject,isLocked)
    if isLocked then
        KTool.SetActive(self.CanAdd.gameObject,not isLocked)
        KTool.SetActive(self.HasAdded.gameObject,not isLocked)
        self.LockDesTxt.text = des
        return
    end
    self.isCanAdd =  tonumber(ownerId) == 0
    KTool.SetActive(self.CanAdd.gameObject,self.isCanAdd)
    KTool.SetActive(self.HasAdded.gameObject,not self.isCanAdd)
    ---不能添加  说明是有owner了
    if not self.isCanAdd then
        ---@type CardComponent
        local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        ---@type CardDojo
        local cardDojo = cardComp:GetCardById(ownerId)
        local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
        local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(vo.additionId)
        ---@type CardVo
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
        if skillVo then
            self.Name.text = cardVo.name
            self.TextDesc.text = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr,vo.additionNum,nil,vo.percentage)
            CfUtils.FillText(self.TextTitle,skillVo.name)
        end
        local skinId = cardVo.defaultSkin
        if cardDojo and isSet(cardDojo, "cardSkin") then
            skinId = checkNumber(cardDojo.cardSkin)
        end
        local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
        CfUtils.FillImage(self.ImgIcon,skillVo.icon)
        CfUtils.FillImage(self.ImgHead,skinVo.buffHead)
        ---设置心情值和状态 会刷新
        local point = tonumber(cardDojo.cafeEnergy) or 0
        KTool.SetActive(self.UIFX_warning.gameObject,point < 50)
        CfUtils.FillText(self.TextNumber,point)
        local status = MaidCoffeeUtils.GetCardMoodStatus(point)
        CfUtils.SetUISwitchText(self.TextNumber,status)
        CfUtils.SetUISwitchImage(self.ImgAttribute,status)

        KTool.SetActive(self.NotEffective.gameObject,point == 0)
        KTool.SetActive(self.ImgNotEnough.gameObject,point == 0)

        local canvasGroup = self.BuffIcon.transform:GetComponent(typeof(CanvasGroup))
        local alpha = point == 0 and 0.5 or 1
        canvasGroup.alpha = alpha
    end
    self:RefreshRedPoint()
end

function OverseaManagerPersonnelClerkCell:RefreshRedPoint()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local redGo = GameUtils.GetRedPointGo(self.BtnNode)
    if redGo then
        local allClerks = component:GetAllClerkIds()
        local isHave = component:GetClerkRedPointByIndex(self.index,allClerks)
        KTool.SetActive(redGo,isHave)
    end
    local isPersonHave = component:IsPersonHaveRedPoint()
    GameUtils.SetRedPointNum(Constants.RedPointConst.MaidCafeStaff,isPersonHave and 1 or 0)
end

function OverseaManagerPersonnelClerkCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

function OverseaManagerPersonnelClerkCell:OnSelectBtnClick()
    if self.isLocked then return end
    local haveData = {}
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)

    for i = 1, 3 do
        local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        table.insert(haveData,{index = i,id = id})
    end

    component:SaveCacheData(haveData)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeePersonSelectDialog , parameters = { type = MaidCoffeeConstants.SelectType.Clerk, data = haveData ,cb = nil } })
end

return OverseaManagerPersonnelClerkCell